# 1. for...else：找到因子就 break，不触发 else
for n in range(2, 10):
    for x in range(2, n):
        if n % x == 0:
            break
    else:
        print(f"{n} is prime")
# 2,3,5,7 is prime

# 2. *args 打包 + **kwargs 打包
def log(level, *messages, **meta):
    for msg in messages:
        print(f"[{level}] {msg}")
    for k, v in meta.items():
        print(f"  {k}: {v}")

log("INFO", "start", "end", user="alice", duration=42)
# messages=('start','end'), meta={'user':'alice','duration':42}

# 3. 强制关键字参数：* 之后的 timeout、ssl 必须用 key=value 传
def connect(host, port, *, timeout=30, ssl=True):
    pass

connect("localhost", 8080)            # ✅
# connect("localhost", 8080, 60)      # ❌ TypeError: takes 2 positional but 3 were given
connect("localhost", 8080, timeout=60) # ✅

# 4. * 和 ** 解包
def point(x, y): return (x, y)

coords = [3, 5]
print(point(*coords))                 # (3, 5) — 列表解包为位置参数

d = {"x": 10, "y": 20}
print(point(**d))                      # (10, 20) — 字典解包为关键字参数

# 5. 默认参数可变对象陷阱
def append_to(item, lst=None):
    if lst is None:
        lst = []        # 每次调用创建新列表
    lst.append(item)
    return lst

print(append_to(1))    # [1]
print(append_to(2))    # [2] — 不是 [1, 2]
